// delivery · кейсы dlv-01, dlv-02, dlv-03, dlv-05 (.qa/tests/delivery/) — только чтение, ничего не сохраняется.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });

const noteLinks = (page: Page) => page.getByRole('link', { name: /^תעודת משלוח · הזמנה #\d+/ });

async function openBoard(page: Page) {
  await page.goto('/delivery');
  await expect(page.getByRole('heading', { level: 1, name: 'משלוחים' })).toBeVisible({ timeout: 20_000 });
}

/** Первая карточка в группе (по h2) с адресом; возвращает href или null. */
async function firstNoteInGroup(page: Page, group: string): Promise<string | null> {
  const heading = page.getByRole('heading', { level: 2, name: group });
  if (!(await heading.count())) return null;
  const section = heading.locator('xpath=ancestor::*[.//a[contains(@href,"/delivery/")]][1]');
  const links = section.getByRole('link', { name: /^תעודת משלוח · הזמנה #\d+/ });
  const n = await links.count();
  for (let i = 0; i < n; i++) {
    const card = links.nth(i).locator('..');
    if (await card.getByText('אין כתובת משלוח').count()) continue;
    return links.nth(i).getAttribute('href');
  }
  return null;
}

test.describe('delivery — לוח משלוחים ותעודת משלוח (מפיץ)', () => {
  test('לוח משלוחים: טקסט הסבר למפיץ, לחיצה על הזמנה פותחת תעודת משלוח עם שיוך נהג #6a70b080 #6a70ae75 @desktop @prod-safe', async ({ page }) => {
    await openBoard(page);
    await expect(page.getByText('לוח החלוקה — ההזמנות שיצאו או מוכנות לצאת. לחצו על הזמנה לפתיחת תעודת המשלוח ולשיוך נהג ומסלול')).toBeVisible();
    await expect(page.getByRole('combobox', { name: 'נהג' })).toBeVisible();
    await expect(page.getByText('סה״כ משלוחים', { exact: true }).filter({ visible: true }).first()).toBeVisible();
    const first = noteLinks(page).first();
    test.skip(!(await first.count()), 'на доске нет משלוחים');
    const no = (await first.getAttribute('aria-label') ?? await first.innerText()).match(/#(\d+)/)?.[1];
    await first.click();
    await expect(page).toHaveURL(/\/delivery\/[0-9a-f-]{36}$/);
    await expect(page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${no}` })).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText(`ת. משלוח #DN-${no}`)).toBeVisible();
    await expect(page.getByText('פרטי משלוח')).toBeVisible();
    await expect(page.getByRole('heading', { level: 2, name: 'שיוך נהג ומסלול' })).toBeVisible();
    await expect(page.getByRole('combobox', { name: 'מסלול חלוקה' })).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'תאריך אספקה' })).toBeVisible();
    await page.getByRole('button', { name: 'חזרה למשלוחים' }).click();
    await expect(page).toHaveURL(/\/delivery$/);
  });

  test('תעודת משלוח: טבלת הפריטים פרוסה על כל הרוחב, «הדפסה / PDF» פותח הדפסה #6a7492a2 #6a70b0b7 @desktop @prod-safe', async ({ page }) => {
    await openBoard(page);
    const first = noteLinks(page).first();
    test.skip(!(await first.count()), 'на доске нет משלוחים');
    await first.click();
    const table = page.getByRole('table');
    await expect(table).toBeVisible({ timeout: 20_000 });
    const headers = table.getByRole('columnheader');
    await expect(headers).toHaveText(['שם פריט', 'מק"ט', 'כמות', 'מחיר יחידה', 'סה״כ']);
    expect(await table.getByRole('row').count()).toBeGreaterThan(1);

    const m = await table.evaluate((t) => {
      const tb = t.getBoundingClientRect();
      const ths = [...t.querySelectorAll('th')].map((th) => th.getBoundingClientRect());
      return { left: tb.left, right: tb.right, width: tb.width, ths: ths.map((r) => ({ left: r.left, right: r.right, width: r.width })) };
    });
    // RTL: первая колонка у правого края, последняя («סה״כ») — у левого; колонки заполняют всю ширину.
    expect(Math.abs(m.ths[0].right - m.right)).toBeLessThanOrEqual(2);
    expect(Math.abs(m.ths[m.ths.length - 1].left - m.left)).toBeLessThanOrEqual(2);
    const sum = m.ths.reduce((s, r) => s + r.width, 0);
    expect(Math.abs(sum - m.width)).toBeLessThanOrEqual(4);
    for (const r of m.ths) expect(r.width).toBeGreaterThan(40);

    await page.evaluate(() => { (window as any).__printed = 0; window.print = () => { (window as any).__printed++; }; });
    await page.getByRole('button', { name: 'הדפסה / PDF' }).click();
    await expect.poll(() => page.evaluate(() => (window as any).__printed)).toBe(1);
  });

  test('הזמנה «בדרך ללקוח» — עדיין ניתן לשנות נהג, מסלול ותאריך אספקה #6a70b080 @desktop @prod-safe', async ({ page }) => {
    await openBoard(page);
    const href = await firstNoteInGroup(page, 'בדרך ללקוח');
    test.skip(!href, 'нет заказа «בדרך ללקוח» с адресом');
    await page.goto(href!);
    await expect(page.getByText('בדרך ללקוח').first()).toBeVisible({ timeout: 20_000 });
    await expect(page.getByRole('combobox', { name: 'נהג' })).toBeEnabled();
    await expect(page.getByRole('combobox', { name: 'מסלול חלוקה' })).toBeEnabled();
    await expect(page.getByRole('textbox', { name: 'תאריך אספקה' })).toBeEnabled();
    await expect(page.getByRole('button', { name: 'שייך ושלח לנהג' })).toBeEnabled();
    await expect(page.getByRole('combobox', { name: 'נהג' }).getByRole('option', { name: 'יוסי הנהג' })).toHaveCount(1);
    // Ничего не сохраняем — заказ чужой.
  });

  test('כרטיס ההזמנה: נהג + תאריך אספקה, «שמירת שיבוץ» נדלק רק אחרי שינוי #6a7491c7 @desktop @prod-safe', async ({ page }) => {
    await openBoard(page);
    const href = (await firstNoteInGroup(page, 'בדרך ללקוח')) ?? (await firstNoteInGroup(page, 'מוכנות למשלוח'));
    test.skip(!href, 'нет заказа на доске с адресом');
    const id = href!.split('/').pop();
    await page.goto(`/orders/${id}`);
    const card = page.getByRole('heading', { level: 3, name: 'משלוח' }).locator('xpath=ancestor::*[.//button[normalize-space()="שמירת שיבוץ"]][1]');
    await expect(card).toBeVisible({ timeout: 20_000 });
    await expect(card.getByText('ניתן לשייך נהג ולעדכן תאריך אספקה בכל שלב — השיוך אינו משנה את סטטוס ההזמנה')).toBeVisible();
    const date = card.getByRole('textbox', { name: 'תאריך אספקה' });
    await expect(card.getByRole('combobox', { name: 'נהג' })).toBeEnabled();
    await expect(date).toBeEnabled();
    const save = card.getByRole('button', { name: 'שמירת שיבוץ' });
    await expect(save).toBeDisabled();
    await date.fill('2030-01-15');
    await expect(save).toBeEnabled();
    await expect(card.getByRole('button', { name: 'תעודת משלוח' })).toBeVisible();
    await page.reload(); // без сохранения
  });
});
